model LegacyArchiveBlob {
  recordId      String              @id @db.Uuid
  contentSha256 String
  sizeBytes     Int
  /// Content-addressed reference into the protected blob root: `legacy-archive/<sha256>.blob`.
  storageRef    String
  mediaType     String?
  createdAt     DateTime            @default(now()) @db.Timestamptz(3)
  record        LegacyArchiveRecord @relation(fields: [recordId], references: [id], onDelete: Cascade, onUpdate: Restrict)
}
